code_changes.fixed_code:
    if gate.resolution.at(gate.needs.primary).reaches(str(path), label):
        rights = gate.resolution.at(gate.needs.primary)
        if principal is not None and not (rights.whole or rights.covers_subtree(str(path))):
            need = LEVEL_RANK[gate.needs.primary]
            async for prefix, level in _postures_beneath(session, tables, profile, str(path)):
                if LEVEL_RANK[level] < need and not rights.covers_subtree(prefix):
                    return denied(path)
        return None

